# envcfg — layered configuration loading
#
# Assembles one configuration dictionary from three layers:
#   1. defaults (lowest priority)
#   2. TOML file (middle)
#   3. environment variables (highest)
#
# Later layers override earlier ones key-by-key. A missing TOML file is not
# an error; the layer is simply skipped. Errors are collected and reported
# together via ConfigError.

import os
import tomllib
from typing import Any


class ConfigError(Exception):
    """Raised when an environment variable cannot be coerced or has no default."""
    pass


# ---------- helpers ----------


def _deep_merge(base: dict[str, Any], override: dict[str, Any]) -> dict[str, Any]:
    """Recursively merge override into base, preserving missing keys from base."""
    result = base.copy()
    for key, value in override.items():
        if key in result and isinstance(result[key], dict) and isinstance(value, dict):
            result[key] = _deep_merge(result[key], value)
        else:
            result[key] = value
    return result


def _coerce(value: str, target_type: type) -> Any:
    """Coerce a string to target_type. Raises ValueError on failure."""
    if target_type is int:
        try:
            return int(value)
        except ValueError:
            raise ValueError(f"not a valid integer: {value!r}")
    if target_type is float:
        try:
            return float(value)
        except ValueError:
            raise ValueError(f"not a valid float: {value!r}")
    if target_type is bool:
        lower = value.lower()
        if lower in ("true", "yes", "1"):
            return True
        if lower in ("false", "no", "0"):
            return False
        raise ValueError(f"not a valid boolean: {value!r}")
    if target_type is str:
        return value
    raise ValueError(f"unsupported target type: {target_type!r}")


